hInboxCandidate $c.Store PR999 RQ-015 C-001 r p})-match'CANDIDATE_SUBSTITUTION') 'Project substitution blocked';$t=Join-Path ([IO.Path]::GetTempPath()) ('ri-id-'+[guid]::NewGuid()+'.db');try{$c=New-RapIntakeContext @() @() @((New-RapIntakeFixture)) $t;$p=Promote-RapFixture $c;$null=Invoke-RapResearchIntakeDecision $c.Store $p;[Rap.NativeSqlite]::Execute($t,"UPDATE ResearchIntakeStore SET RecordHash='x' WHERE StoreId='PRIMARY';",5000);A ID12 (-not(Test-RapResearchIntakeStoreIntegrity $t)) 'persisted identity tampering blocked'}finally{Remove-Item $t -Force -ErrorAction SilentlyContinue}
